// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("a new account is empty", () -> eq(new BankAccount("Ada").balance(), 0));
    test("requires an owner", () -> {
        raises(IllegalArgumentException.class, () -> new BankAccount(" "));
        raises(IllegalArgumentException.class, () -> new BankAccount(null));
    });
    test("deposits and withdrawals move the balance", () -> {
        var acct = new BankAccount("Ada");
        acct.deposit(5_000);
        acct.withdraw(1_250);
        eq(acct.balance(), 3_750);
    });
    test("refuses non-positive amounts", () -> {
        var acct = new BankAccount("Ada");
        raises(IllegalArgumentException.class, () -> acct.deposit(0));
        raises(IllegalArgumentException.class, () -> acct.deposit(-5));
        raises(IllegalArgumentException.class, () -> acct.withdraw(-5));
    });
    test("refuses to overdraw", () -> {
        var acct = new BankAccount("Ada");
        acct.deposit(100);
        raises(IllegalStateException.class, () -> acct.withdraw(101));
    });
    test("a refused withdrawal changes nothing", () -> {
        var acct = new BankAccount("Ada");
        acct.deposit(100);
        raises(IllegalStateException.class, () -> acct.withdraw(500));
        eq(acct.balance(), 100);
    });
    test("can withdraw everything", () -> {
        var acct = new BankAccount("Ada");
        acct.deposit(100);
        acct.withdraw(100);
        eq(acct.balance(), 0);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("ignores dashes and spaces", () ->
        eq(new Isbn("978-0-441-17271-9").equals(new Isbn("978 0441172719")), true));
    test("different digits are different", () ->
        eq(new Isbn("9780441172719").equals(new Isbn("9780141439518")), false));
    test("is never equal to null or a String", () -> {
        var isbn = new Isbn("9780441172719");
        eq(isbn.equals(null), false);
        eq(isbn.equals("9780441172719"), false);
    });
    test("equal isbns hash alike", () ->
        eq(new Isbn("978-0-441-17271-9").hashCode(), new Isbn("9780441172719").hashCode()));
    test("a set keeps one copy", () -> {
        var set = new HashSet<Isbn>();
        set.add(new Isbn("978-0-441-17271-9"));
        set.add(new Isbn("9780441172719"));
        eq(set.size(), 1);
    });
    test("a map finds a book by an equal isbn", () -> {
        var titles = new HashMap<Isbn, String>();
        titles.put(new Isbn("978-0-441-17271-9"), "Dune");
        eq(titles.get(new Isbn("9780441172719")), "Dune");
    });
    test("refuses the wrong number of digits", () -> {
        raises(IllegalArgumentException.class, () -> new Isbn("978-0"));
        raises(IllegalArgumentException.class, () -> new Isbn("97804411727190"));
    });
    test("prints as plain digits", () -> eq(new Isbn("978-0-441-17271-9").toString(), "9780441172719"));
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("fromCode finds a priority by its code", () -> eq(Priority.fromCode("H"), Priority.HIGH));
    test("fromCode ignores case", () -> eq(Priority.fromCode("m"), Priority.MEDIUM));
    test("fromCode refuses an unknown code", () -> {
        raises(IllegalArgumentException.class, () -> Priority.fromCode("X"));
        raises(IllegalArgumentException.class, () -> Priority.fromCode("MEDIUM"));
    });
    test("raise moves one step more urgent", () -> {
        eq(Priority.LOW.raise(), Priority.MEDIUM);
        eq(Priority.MEDIUM.raise(), Priority.HIGH);
    });
    test("raise stops at HIGH", () -> eq(Priority.HIGH.raise(), Priority.HIGH));
    test("countAll counts and keeps every key", () ->
        eq(countAll(List.of(Priority.HIGH, Priority.LOW, Priority.HIGH)),
            Map.of(Priority.LOW, 1, Priority.MEDIUM, 0, Priority.HIGH, 2)));
    test("countAll iterates in enum order", () ->
        eq(new ArrayList<>(countAll(List.of()).keySet()), List.of(Priority.LOW, Priority.MEDIUM, Priority.HIGH)));
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("no discount keeps the price", () -> eq(new NoDiscount().apply(1234), 1234));
    test("percent off takes the percentage", () -> eq(new PercentOff(10).apply(2000), 1800));
    test("percent off rounds the discount half up", () -> {
        eq(new PercentOff(15).apply(999), 849);
        eq(new PercentOff(50).apply(1), 0);
    });
    test("amount off subtracts", () -> eq(new AmountOff(300).apply(2000), 1700));
    test("amount off never goes below zero", () -> eq(new AmountOff(500).apply(300), 0));
    test("best picks the lowest price", () -> {
        List<Discount> offers = List.of(new PercentOff(10), new AmountOff(300));
        eq(best(offers, 2000), new AmountOff(300));
        eq(best(offers, 5000), new PercentOff(10));
    });
    test("best keeps the first on a tie", () ->
        eq(best(List.of(new PercentOff(10), new AmountOff(200)), 2000), new PercentOff(10)));
    test("best of nothing is no discount", () -> eq(best(List.of(), 2000).apply(2000), 2000));
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("builds a question from chained calls", () ->
        eq(twoPlusTwo().answer(1).points(2).build(), new Question("2 + 2?", List.of("3", "4"), 1, 2)));
    test("points default to one", () -> eq(twoPlusTwo().answer(1).build().points(), 1));
    test("requires text", () ->
        raises(IllegalStateException.class, () -> Question.builder().option("a").option("b").answer(0).build()));
    test("requires at least two options", () ->
        raises(IllegalStateException.class, () -> Question.builder().text("?").option("a").answer(0).build()));
    test("the answer must be one of the options", () -> {
        raises(IllegalStateException.class, () -> twoPlusTwo().answer(2).build());
        raises(IllegalStateException.class, () -> twoPlusTwo().build());
    });
    test("refuses zero points", () -> raises(IllegalStateException.class, () -> twoPlusTwo().answer(1).points(0).build()));
    test("a built question does not change when the builder does", () -> {
        var builder = twoPlusTwo().answer(1);
        var q = builder.build();
        builder.option("5");
        eq(q.options(), List.of("3", "4"));
    });
    test("a built question's options are read-only", () ->
        raises(UnsupportedOperationException.class, () -> twoPlusTwo().answer(1).build().options().add("x")));
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

