public static void main(String[] args) {
    test("add to an empty list starts at id 1", () ->
        eq(apply(List.of(), new Add("milk")), List.of(new Task(1, "milk", false))));
    test("add uses the highest id plus one", () -> eq(apply(TWO, new Add("bread")).get(2), new Task(5, "bread", false)));
    test("complete marks one task done", () ->
        eq(apply(TWO, new Complete(4)), List.of(new Task(1, "milk", false), new Task(4, "eggs", true))));
    test("rename changes only the title", () ->
        eq(apply(TWO, new Rename(1, "oat milk")), List.of(new Task(1, "oat milk", false), new Task(4, "eggs", false))));
    test("an unknown id is an error", () -> {
        raises(IllegalArgumentException.class, () -> apply(TWO, new Complete(9)));
        raises(IllegalArgumentException.class, () -> apply(TWO, new Rename(9, "x")));
    });
    test("the input list never changes", () -> {
        var tasks = new ArrayList<>(TWO);
        apply(tasks, new Add("bread"));
        apply(tasks, new Complete(1));
        eq(tasks, TWO);
    });
    test("describes each command", () -> {
        eq(describe(new Add("milk")), "add milk");
        eq(describe(new Complete(3)), "complete #3");
        eq(describe(new Rename(2, "eggs")), "rename #2 to eggs");
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("totals quantity times unit price", () -> eq(new Order(List.of(TEA, CAKE)).total(), 1200));
    test("refuses an empty order", () -> raises(IllegalArgumentException.class, () -> new Order(List.of())));
    test("refuses a line with no quantity", () ->
        raises(IllegalArgumentException.class, () -> new Order(List.of(TEA, new Line("X", 0, 100)))));
    test("keeps its own copy of the lines", () -> {
        var lines = new ArrayList<>(List.of(TEA));
        var order = new Order(lines);
        lines.add(CAKE);
        eq(order.lines(), List.of(TEA));
    });
    test("lines cannot be changed through the getter", () ->
        raises(UnsupportedOperationException.class, () -> new Order(List.of(TEA)).lines().add(CAKE)));
    test("withLine returns a bigger order", () -> {
        var bigger = new Order(List.of(TEA)).withLine(CAKE);
        eq(bigger.lines(), List.of(TEA, CAKE));
        eq(bigger.total(), 1200);
    });
    test("withLine leaves the original alone", () -> {
        var order = new Order(List.of(TEA));
        order.withLine(CAKE);
        eq(order.lines(), List.of(TEA));
    });
    test("withLine validates the new line", () ->
        raises(IllegalArgumentException.class, () -> new Order(List.of(TEA)).withLine(new Line("X", -1, 5))));
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

